function validate(input) {
  const [{ Servers = [] }] = input;
  const seen = new Set(), first = new Map(), last = new Map();
  for (const [server, time, status] of Servers) {
    if (server === null) return 'Every row needs a server_id.';
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(time ?? '')) return `status_time must look like 2023-11-02 19:14:15 (server ${server}).`;
    if (status !== 'start' && status !== 'stop') return "session_status must be 'start' or 'stop'.";
    const key = `${server}|${time}`;
    if (seen.has(key)) return `Server ${server} has two rows at ${time}.`;
    seen.add(key);
    if (!first.has(server) || time < first.get(server)[0]) first.set(server, [time, status]);
    if (!last.has(server) || time > last.get(server)[0]) last.set(server, [time, status]);
  }
  for (const [server, [, status]] of first) if (status !== 'start') return `Server ${server} must begin with a start.`;
  for (const [server, [, status]] of last) if (status !== 'stop') return `Server ${server} must end with a stop.`;
  return null;
}

