function generate(rand, size) {
  const small = size === 'small';
  // Sessions are a start and a stop; small cases pack them into a few days on a few servers so they often overlap.
  const sessions = small ? Math.floor(rand() * 5) : 1000;
  const servers = small ? 3 : 20;
  const base = Date.UTC(2023, 10, 1) / 1000;
  const lengths = [59, 3600, 17400, 43200, 86399, 86400, 90000];
  const stamp = t => new Date(t * 1000).toISOString().slice(0, 19).replace('T', ' ');
  const used = new Set(), Servers = [];
  for (let made = 0, tries = 0; made < sessions && tries < sessions * 5; tries++) {
    const server = 1 + Math.floor(rand() * servers);
    const start = base + Math.floor(rand() * (small ? 3 : 29) * 86400);
    const length = small ? lengths[Math.floor(rand() * lengths.length)] : 60 + Math.floor(rand() * 36000);
    const a = `${server}|${start}`, b = `${server}|${start + length}`;
    if (used.has(a) || used.has(b)) continue;
    used.add(a); used.add(b);
    Servers.push([server, stamp(start), 'start'], [server, stamp(start + length), 'stop']);
    made++;
  }
  return [{ Servers }];
}
